        $this->transport->send(
            Endpoint::post('/orgs/{org}/{security_product}/{enablement}')
                ->path('org', $org)
                ->path('security_product', $securityProduct)
                ->path('enablement', $enablement)
                ->json($body),
            ResponseType::nothing(),
        );
    }

